import { Diagnostic } from '@servicenow/sdk-build-core'
import { createProject } from '../test-utils'

const SCOPE = 'global'

describe('UI Policy Plugin', () => {
    describe('Fluent to XML', () => {
        test('xml created with expected defaults', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const recordId = project.registerExplicitId('sys_ui_policy', 'basic_policy')
            const fluentFile = project.addFile({
                path: 'src/fluent/basic-policy.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['basic_policy'],
    table: 'incident',
    shortDescription: 'Basic UI Policy Test',
})
`,
            })

            const record = (await fluentFile.getRecords()).query('sys_ui_policy')[0]
            expect(record.getId().getValue()).toBe(recordId)
            expect(record.getValue()).toMatchObject({
                table: 'incident',
                short_description: 'Basic UI Policy Test',
                active: true,
                global: true, // Plugin default is true
                on_load: true,
                reverse_if_false: true, // Plugin default is true
                inherit: false,
                isolate_script: false,
                run_scripts: false,
                order: 100,
                ui_type: 0,
                conditions: '',
                script_true: 'function onCondition() {\n\n}', // Plugin adds default function
                script_false: 'function onCondition() {\n\n}', // Plugin adds default function
                description: '',
                model_id: '',
                model_table: '',
                set_values: '',
                view: '',
            })
        })

        test('UI Policy with scripts', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const recordId = project.registerExplicitId('sys_ui_policy', 'policy_with_scripts')
            const fluentFile = project.addFile({
                path: 'src/fluent/policy-with-scripts.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['policy_with_scripts'],
    table: 'incident',
    shortDescription: 'Policy with Scripts',
    runScripts: true,
    uiType: 'desktop',
    scriptTrue: 'function onCondition() { g_form.addErrorMessage("Error"); }',
    scriptFalse: 'function onCondition() { g_form.clearMessages(); }',
    conditions: 'state=1',
    global: true,
    reverseIfFalse: true,
    isolateScript: true,
})
`,
            })

            const diagnostics = await fluentFile.getDiagnostics()
            if (diagnostics.length > 0) {
                throw new Error(`Diagnostics: ${diagnostics.map((d) => d.message).join('; ')}`)
            }
            const record = (await fluentFile.getRecords()).query('sys_ui_policy')[0]
            if (!record) {
                throw new Error('No UI Policy record found')
            }
            expect(record.getId().getValue()).toBe(recordId)
            expect(record.getValue()).toMatchObject({
                table: 'incident',
                short_description: 'Policy with Scripts',
                run_scripts: true,
                script_true: 'function onCondition() { g_form.addErrorMessage("Error"); }',
                script_false: 'function onCondition() { g_form.clearMessages(); }',
                conditions: 'state=1',
                global: true,
                reverse_if_false: true,
                isolate_script: true,
                active: true,
                on_load: true,
            })
        })

        test('UI Policy with actions', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const policyId = project.registerExplicitId('sys_ui_policy', 'policy_with_actions')
            // Actions use coalesce keys [ui_policy, field], but we don't need to register them explicitly

            const fluentFile = project.addFile({
                path: 'src/fluent/policy-with-actions.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['policy_with_actions'],
    table: 'incident',
    shortDescription: 'Policy with Actions',
    actions: [
        {
            field: 'priority',
            visible: false,
            mandatory: 'ignore',
            readOnly: 'ignore',
        },
        {
            field: 'urgency',
            visible: 'ignore',
            mandatory: true,
            readOnly: false,
        }
    ]
})
`,
            })

            const records = await fluentFile.getRecords()
            const policyRecord = records.query('sys_ui_policy')[0]
            const actionRecords = records.query('sys_ui_policy_action')

            expect(policyRecord.getId().getValue()).toBe(policyId)
            expect(actionRecords).toHaveLength(2)

            const action1 = actionRecords.find((r) => r.getValue()['field'] === 'priority')
            const action2 = actionRecords.find((r) => r.getValue()['field'] === 'urgency')

            expect(action1?.getValue()).toMatchObject({
                field: 'priority',
                visible: 'false',
                mandatory: 'ignore',
                disabled: 'ignore', // readOnly: 'ignore' in Fluent becomes disabled: 'ignore' in database
                ui_policy: policyId,
            })

            expect(action2?.getValue()).toMatchObject({
                field: 'urgency',
                visible: 'ignore',
                mandatory: 'true',
                disabled: 'false', // readOnly: false in Fluent becomes disabled: 'false' in database
                ui_policy: policyId,
            })
        })

        test('UI Policy with related list actions', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const policyId = project.registerExplicitId('sys_ui_policy', 'policy_with_related_lists')
            project.registerExplicitId('sys_ui_policy_rl_action', 'rl_action_1')

            const fluentFile = project.addFile({
                path: 'src/fluent/policy-with-related-lists.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['policy_with_related_lists'],
    table: 'incident',
    shortDescription: 'Policy with Related List Actions',
    relatedListActions: [
        {
            list: 'b9edf0ca0a0a0b010035de2d6b579a03',
            visible: false,
        }
    ]
})
`,
            })

            const records = await fluentFile.getRecords()
            const policyRecord = records.query('sys_ui_policy')[0]
            const rlActionRecords = records.query('sys_ui_policy_rl_action')
            expect(policyRecord.getId().getValue()).toBe(policyId)
            expect(rlActionRecords).toHaveLength(1)

            const rlAction = rlActionRecords[0]
            // Just check that we have the right record, ID generation is complex for coalesced records
            expect(rlAction).toBeDefined()
            expect(rlAction.getValue()).toMatchObject({
                list: 'REL:b9edf0ca0a0a0b010035de2d6b579a03',
                visible: 'false',
                ui_policy: policyId,
            })
        })

        test('UI Policy with field messages and camelCase properties', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const policyId = project.registerExplicitId('sys_ui_policy', 'policy_with_field_messages')

            const fluentFile = project.addFile({
                path: 'src/fluent/policy-with-field-messages.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['policy_with_field_messages'],
    table: 'incident',
    shortDescription: 'Policy with Field Messages',
    actions: [
        {
            field: 'priority',
            visible: true,
            readOnly: false,
            mandatory: true,
            fieldMessage: 'Please select a priority level',
            fieldMessageType: 'info',
        },
        {
            field: 'urgency',
            visible: true,
            readOnly: true,
            fieldMessage: 'This field is read-only',
            fieldMessageType: 'warning',
            valueAction: 'set_value',
        }
    ]
})
`,
            })

            const records = await fluentFile.getRecords()
            const policyRecord = records.query('sys_ui_policy')[0]
            const actionRecords = records.query('sys_ui_policy_action')

            expect(policyRecord.getId().getValue()).toBe(policyId)
            expect(actionRecords).toHaveLength(2)

            const action1 = actionRecords.find((r) => r.getValue()['field'] === 'priority')
            const action2 = actionRecords.find((r) => r.getValue()['field'] === 'urgency')

            // Verify camelCase properties are converted to snake_case in database
            expect(action1?.getValue()).toMatchObject({
                field: 'priority',
                visible: 'true',
                disabled: 'false', // active=true inverted to disabled='false'
                mandatory: 'true',
                field_message: 'Please select a priority level',
                field_message_type: 'info',
                ui_policy: policyId,
            })

            expect(action2?.getValue()).toMatchObject({
                field: 'urgency',
                visible: 'true',
                disabled: 'true', // active=false inverted to disabled='true'
                field_message: 'This field is read-only',
                field_message_type: 'warning',
                value_action: 'set_value',
                ui_policy: policyId,
            })
        })

        test('converts UI type between string and number', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            project.registerExplicitId('sys_ui_policy', 'ui_type_test')

            const fluentFile = project.addFile({
                path: 'src/fluent/ui-type-test.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['ui_type_test'],
    table: 'incident',
    shortDescription: 'UI Type Test',
    uiType: 'mobile-or-service-portal',
})
`,
            })

            const record = (await fluentFile.getRecords()).query('sys_ui_policy')[0]
            expect(record.getValue()['ui_type']).toBe(1)
        })
    })

    describe('Validation', () => {
        test('validates action properties', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const fluentFile = project.addFile({
                path: 'src/fluent/invalid-action.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['invalid_action_policy'],
    table: 'incident',
    shortDescription: 'Invalid Action Policy',
    actions: [
        {
            // Missing required field property
            visible: true,
        }
    ]
})
`,
            })

            const diagnostics = await fluentFile.getDiagnostics()
            expect(diagnostics.length).toBeGreaterThan(0)

            const messages = diagnostics.map((d) => d.message)
            expect(messages.some((m) => m.includes('field'))).toBe(true)
        })

        test('provides an info diagnostic if scriptTrue or scriptFalse are set with non-default values and runScripts is not explicitly set (defaults to false)', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const fluentFile = project.addFile({
                path: 'src/fluent/info-diagnostic.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['test_ui_policy'],
    shortDescription: 'Some Policy',
    scriptTrue: '// some script',
})
`,
            })

            const diagnostics = await fluentFile.getDiagnostics()
            expect(diagnostics.length).toBeGreaterThan(0)

            const messages = diagnostics.map((d) => ({ level: d.level, message: d.message }))

            expect(messages).toEqual([
                {
                    level: Diagnostic.Level.Info,
                    message: 'This script will not execute unless runScripts is set to true',
                },
            ])
        })

        test('validates action has at least one property', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const fluentFile = project.addFile({
                path: 'src/fluent/empty-action.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['empty_action_policy'],
    table: 'incident',
    shortDescription: 'Empty Action Policy',
    actions: [
        {
            field: 'priority',
            // No action properties specified - should be invalid
        }
    ]
})
`,
            })

            const diagnostics = await fluentFile.getDiagnostics()
            expect(diagnostics.length).toBeGreaterThan(0)

            const messages = diagnostics.map((d) => d.message)
            expect(
                messages.some((m) =>
                    m.includes('must specify at least one of: visible, readOnly, mandatory, or cleared')
                )
            ).toBe(true)
        })

        test('validates table scope prefix for scoped apps', async () => {
            const project = createProject({ config: { scope: 'x_test' } })
            const fluentFile = project.addFile({
                path: 'src/fluent/invalid-scope-policy.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['invalid_scope_policy'],
    table: 'incident', // Should fail - not prefixed with x_test_
    shortDescription: 'Invalid Scope Policy',
})
`,
            })

            const diagnostics = await fluentFile.getDiagnostics()
            expect(diagnostics.length).toBeGreaterThan(0)

            const messages = diagnostics.map((d) => d.message)
            expect(messages.some((m) => m.includes("'table' property should start with scope prefix 'x_test_'"))).toBe(
                true
            )
        })

        test('allows table without scope prefix for global scope', async () => {
            const project = createProject({ config: { scope: 'global' } })
            const fluentFile = project.addFile({
                path: 'src/fluent/global-policy.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['global_policy'],
    table: 'incident', // Should pass - global scope
    shortDescription: 'Global Policy',
})
`,
            })

            const diagnostics = await fluentFile.getDiagnostics()
            const scopeErrors = diagnostics.filter((d) => d.message.includes('scope prefix'))
            expect(scopeErrors.length).toBe(0)
        })

        test('allows correctly prefixed table for scoped apps', async () => {
            const project = createProject({ config: { scope: 'x_test' } })
            const fluentFile = project.addFile({
                path: 'src/fluent/valid-scope-policy.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['valid_scope_policy'],
    table: 'x_test_custom_table', // Should pass - correctly prefixed
    shortDescription: 'Valid Scope Policy',
})
`,
            })

            const diagnostics = await fluentFile.getDiagnostics()
            const scopeErrors = diagnostics.filter((d) => d.message.includes('scope prefix'))
            expect(scopeErrors.length).toBe(0)
        })
    })

    describe('XML to Fluent', () => {
        test('transforms UI Policy XML to Fluent', async () => {
            const project = createProject({ config: { scope: SCOPE }, rootDir: __dirname })
            const output = await project.transform('./xml/sys_ui_policy.xml')

            expect(output.changedFiles).toHaveLength(1)
            expect(output.changedFiles[0].getName()).toBe('sys_ui_policy.now.ts')

            const content = output.changedFiles[0].getContent()
            expect(content).toContain("import { UiPolicy } from '@servicenow/sdk/core'")
            expect(content).toContain("table: 'x_snc_aiconference_session'")
            expect(content).toContain("shortDescription: 'When Speaker has value, Apply the policy'")
            expect(content).toContain("description: 'Test UI Policy for speaker validation'")
            expect(content).toContain("conditions: 'speakerISNOTEMPTY^EQ'")
            // Properties with default values are omitted for cleaner code
            // expect(content).toContain('global: true') - omitted as it's the default
            // expect(content).toContain('onLoad: true') - omitted as it's the default
            // expect(content).toContain('reverseIfFalse: true') - omitted as it's the default
            // expect(content).toContain('inherit: false') - omitted as it's the default
            expect(content).toContain('isolateScript: true') // Non-default value, should be included
            expect(content).toContain('runScripts: true') // Non-default value, should be included
            expect(content).toContain("uiType: 'mobile-or-service-portal'") // ui_type: 1 in XML
            // expect(content).toContain('order: 100') - omitted as it's the default
            expect(content).toContain('scriptTrue: `function onCondition() {')
            expect(content).toContain("g_form.addErrorMessage('Speaker is required for this session type');")
            expect(content).toContain('scriptFalse: `function onCondition() {')
            expect(content).toContain('g_form.clearMessages();')
        })

        test('transforms UI Policy Action XML to Fluent', async () => {
            const project = createProject({ config: { scope: SCOPE }, rootDir: __dirname })
            // First transform the policy, then the action
            await project.transform('./xml/sys_ui_policy.xml')
            const output = await project.transform('./xml/sys_ui_policy_action.xml')

            expect(output.changedFiles).toHaveLength(1)
            const content = output.changedFiles[0].getContent()

            // Check that the action is added to the policy's actions array
            expect(content).toContain('actions: [')
            expect(content).toContain("field: 'end_time'")
            expect(content).toContain('visible: false')
            // Properties with 'ignore' values are omitted for cleaner code
            expect(content).not.toContain("readOnly: 'ignore'")
            expect(content).not.toContain("mandatory: 'ignore'")
        })

        test('transforms multiple UI Policy Actions to Fluent', async () => {
            const project = createProject({ config: { scope: SCOPE }, rootDir: __dirname })
            // Transform policy and both actions
            await project.transform('./xml/sys_ui_policy.xml')
            await project.transform('./xml/sys_ui_policy_action.xml')
            const output = await project.transform('./xml/sys_ui_policy_action_2.xml')

            expect(output.changedFiles).toHaveLength(1)
            const content = output.changedFiles[0].getContent()

            // Check that both actions are in the array
            expect(content).toContain("field: 'end_time'")
            expect(content).toContain("field: 'room'")
            expect(content).toContain('mandatory: true')
        })

        test('transforms UI Policy Related List Action XML to Fluent', async () => {
            const project = createProject({ config: { scope: SCOPE }, rootDir: __dirname })
            // First transform the policy, then the related list action
            await project.transform('./xml/sys_ui_policy.xml')
            const output = await project.transform('./xml/sys_ui_policy_rl_action.xml')

            expect(output.changedFiles).toHaveLength(1)
            const content = output.changedFiles[0].getContent()

            // Check that the related list action is added to the policy's relatedListActions array
            expect(content).toContain('relatedListActions: [')
            expect(content).toContain("list: 'b9edf0ca0a0a0b010035de2d6b579a03'")
            expect(content).toContain('visible: false')
        })

        test('roundtrip: XML -> Fluent -> XML maintains data integrity', async () => {
            const project = createProject({ config: { scope: SCOPE }, rootDir: __dirname })
            // Transform XML to Fluent
            await project.transform('./xml/sys_ui_policy.xml')
            await project.transform('./xml/sys_ui_policy_action.xml')
            await project.transform('./xml/sys_ui_policy_action_2.xml')
            const rlOutput = await project.transform('./xml/sys_ui_policy_rl_action.xml')

            // Verify the transform created a Fluent file
            expect(rlOutput.changedFiles.length).toBeGreaterThan(0)
            const fluentFile = rlOutput.changedFiles[0]
            const content = fluentFile.getContent()

            // Verify the generated Fluent code contains expected elements with boolean format
            expect(content).toContain('UiPolicy')
            expect(content).toContain("table: 'x_snc_aiconference_session'")
            expect(content).toContain('actions: [')
            expect(content).toContain('relatedListActions: [')
            expect(content).toContain("field: 'end_time'")
            expect(content).toContain("field: 'room'")

            // Verify boolean format is used (not string format)
            expect(content).toContain('visible: false') // Boolean, not 'false'
            expect(content).toContain('mandatory: true') // Boolean, not 'true'
            expect(content).not.toContain("visible: 'false'") // Should not have string format
            expect(content).not.toContain("mandatory: 'true'") // Should not have string format
        })
    })

    describe('Advanced Features', () => {
        test('handles complex policy with all features', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const policyId = project.registerExplicitId('sys_ui_policy', 'complex_policy')
            project.registerExplicitId('sys_ui_policy_rl_action', 'complex_rl_action')

            const fluentFile = project.addFile({
                path: 'src/fluent/complex-policy.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['complex_policy'],
    table: 'x_snc_aiconference_session',
    shortDescription: 'Complex Policy with All Features',
    description: 'A comprehensive test policy',
    conditions: 'speakerISNOTEMPTY^EQ',
    global: true,
    onLoad: true,
    reverseIfFalse: true,
    inherit: false,
    isolateScript: true,
    runScripts: true,
    scriptTrue: 'function onCondition() { g_form.addErrorMessage("Speaker is required"); }',
    scriptFalse: 'function onCondition() { g_form.clearMessages(); }',
    order: 200,
    uiType: 'mobile-or-service-portal',
    view: 'mobile',
    setValues: 'priority=1^urgency=1',
    modelId: 'test_model',
    modelTable: 'test_model_table',
    actions: [
        {
            field: 'end_time',
            visible: false,
            readOnly: 'ignore',
            mandatory: 'ignore',
        },
        {
            field: 'room',
            visible: 'ignore',
            readOnly: false,
            mandatory: true,
        }
    ],
    relatedListActions: [
        {
            list: 'b9edf0ca0a0a0b010035de2d6b579a03',
            visible: false,
        }
    ]
})
`,
            })

            const records = await fluentFile.getRecords()
            const policyRecord = records.query('sys_ui_policy')[0]
            const actionRecords = records.query('sys_ui_policy_action')
            const rlActionRecords = records.query('sys_ui_policy_rl_action')

            // Verify policy record
            expect(policyRecord.getId().getValue()).toBe(policyId)
            expect(policyRecord.getValue()).toMatchObject({
                table: 'x_snc_aiconference_session',
                short_description: 'Complex Policy with All Features',
                description: 'A comprehensive test policy',
                conditions: 'speakerISNOTEMPTY^EQ',
                global: true,
                on_load: true,
                reverse_if_false: true,
                inherit: false,
                isolate_script: true,
                run_scripts: true,
                script_true: 'function onCondition() { g_form.addErrorMessage("Speaker is required"); }',
                script_false: 'function onCondition() { g_form.clearMessages(); }',
                order: 200,
                ui_type: 1, // mobile-service-portal converts to 1
                view: 'mobile',
                set_values: 'priority=1^urgency=1',
                model_id: 'test_model',
                model_table: 'test_model_table',
            })

            // Verify action records
            expect(actionRecords).toHaveLength(2)
            const action1 = actionRecords.find((r) => r.getValue()['field'] === 'end_time')
            const action2 = actionRecords.find((r) => r.getValue()['field'] === 'room')

            expect(action1?.getValue()).toMatchObject({
                field: 'end_time',
                visible: 'false',
                ui_policy: policyId,
            })

            expect(action2?.getValue()).toMatchObject({
                field: 'room',
                disabled: 'false', // readOnly: false in Fluent becomes disabled: 'false' in database
                mandatory: 'true',
                ui_policy: policyId,
            })

            // Verify related list action records
            expect(rlActionRecords).toHaveLength(1)
            const rlAction1 = rlActionRecords[0]
            expect(rlAction1.getValue()).toMatchObject({
                list: 'REL:b9edf0ca0a0a0b010035de2d6b579a03',
                visible: 'false',
                ui_policy: policyId,
            })
        })

        test('handles empty actions and related list actions arrays', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const recordId = project.registerExplicitId('sys_ui_policy', 'empty_actions_policy')

            const fluentFile = project.addFile({
                path: 'src/fluent/empty-actions-policy.now.ts',
                content: `import { UiPolicy } from '@servicenow/sdk/core'

UiPolicy({
    $id: Now.ID['empty_actions_policy'],
    table: 'incident',
    shortDescription: 'Policy with Empty Actions',
    actions: [],
    relatedListActions: [],
})
`,
            })

            const records = await fluentFile.getRecords()
            const policyRecord = records.query('sys_ui_policy')[0]
            const actionRecords = records.query('sys_ui_policy_action')
            const rlActionRecords = records.query('sys_ui_policy_rl_action')

            expect(policyRecord.getId().getValue()).toBe(recordId)
            expect(actionRecords).toHaveLength(0)
            expect(rlActionRecords).toHaveLength(0)
        })
    })
})
